import XCTest
@testable import PhotoCraftCore

final class LayerLinksTests:XCTestCase {
  func fixture(_ depth:PixelDepth = .u8)throws->CraftDocument{var d=try LayerCollectionTransformTests().fixture(depth);d.layers.append(Layer(name:"C",content:.raster(try Surface(width:2,height:2,depth:depth,fill:.white))));d.layers[2].x=15;d.layers[2].y=11;return d}
  func testPersistentMergeDisableEnableAndUnlinkKeepIdentityAndSamples()throws{
    var d=try fixture();let source=d,ids=d.layers.map(\.id);try Command.layerLinks(.link([ids[0],ids[1]])).apply(to:&d);let group=try XCTUnwrap(d.layers[0].linkID);XCTAssertEqual(d.layers[1].linkID,group);try Command.layerLinks(.link([ids[0],ids[1]])).apply(to:&d);XCTAssertEqual(d.layers[0].linkID,group);try Command.layerLinks(.enabled([ids[1]],false)).apply(to:&d);XCTAssertEqual(d.layers[1].linkDisabled,true);try Command.layerLinks(.link([ids[0],ids[2]])).apply(to:&d);XCTAssertEqual(Set(d.layers.compactMap(\.linkID)).count,1);XCTAssertEqual(d.layers[1].linkDisabled,true);try Command.layerLinks(.unlink([ids[0]])).apply(to:&d);XCTAssertNil(d.layers[0].linkID);XCTAssertNotNil(d.layers[1].linkID);try Command.layerLinks(.unlink([ids[2]])).apply(to:&d);XCTAssertTrue(d.layers.allSatisfy{$0.linkID==nil && $0.linkDisabled==nil});XCTAssertEqual(d.layers.map(\.content),source.layers.map(\.content));XCTAssertEqual(d.layers.map(\.id),ids)
  }
  func testTransitiveLinkedGroupDescendantsExpandOnceAndDisabledMembersStayIndependent()throws{
    var d=try fixture();let a=d.layers[0].id,b=d.layers[1].id,c=d.layers[2].id;try Command.groupLayers([a],"Group").apply(to:&d);let group=try XCTUnwrap(d.activeLayerID);try Command.layerLinks(.link([group,b])).apply(to:&d);try Command.layerLinks(.link([a,c])).apply(to:&d);XCTAssertEqual(LayerLinks.expanded(in:d,layerIDs:[group]),Set(d.layers.map(\.id)));let before=d;try Command.moveLayers(.init(layerIDs:[group,a],dx:3,dy:2)).apply(to:&d);for layer in before.layers{XCTAssertEqual(d.layers.first{$0.id==layer.id}?.x,layer.x+3);XCTAssertEqual(d.layers.first{$0.id==layer.id}?.y,layer.y+2)};try Command.layerLinks(.enabled([b],false)).apply(to:&d);XCTAssertFalse(LayerLinks.expanded(in:d,layerIDs:[group]).contains(b));XCTAssertEqual(LayerLinks.expanded(in:d,layerIDs:[b]),[b]);XCTAssertEqual(LayerLinks.related(in:d,layerIDs:[b]),[group,b])
  }
  func testWholeMoveThreeDepthsKeepsAllStoredWordsAndUnlinkedMasksInPlace()throws{
    for depth in PixelDepth.allCases{var d=try fixture(depth);d.layers[0].mask=try Surface(width:3,height:2,depth:depth,fill:.white);var properties=MaskProperties();properties.linked=false;properties.density=0.7;d.layers[0].maskProperties=properties;try Command.layerLinks(.link([d.layers[0].id,d.layers[1].id])).apply(to:&d);let before=d;try Command.move(d.layers[0].id,d.layers[0].x+4,d.layers[0].y+3).apply(to:&d);for i in 0..<2{XCTAssertEqual(d.layers[i].content,before.layers[i].content);XCTAssertEqual(d.layers[i].x,before.layers[i].x+4);XCTAssertEqual(d.layers[i].y,before.layers[i].y+3)};XCTAssertEqual(d.layers[0].mask,before.layers[0].mask);XCTAssertEqual(d.layers[0].maskCoordinateTransform,before.layers[0].maskCoordinateTransform);XCTAssertEqual(d.layers[2],before.layers[2])}
  }
  func testAffineAndProjectiveTransformsUseLinkedTargetsAndPreserveProtectionAtomicity()throws{
    var source=try fixture();let ids=Array(source.layers.prefix(2).map(\.id));try Command.layerLinks(.link(ids)).apply(to:&source);let matrix=Transform2D.translation(3,2);var a=source,b=source;try Command.transform(ids[0],matrix,.nearest).apply(to:&a);try Command.transformLayers(.init(layerIDs:ids,matrix:matrix,interpolation:.nearest)).apply(to:&b);XCTAssertEqual(a,b)
    let projection=try ProjectiveTransform([1,0.1,1,0,1,1,0.01,0.005,1]);a=source;b=source;try Command.transformLayers(.init(layerIDs:[ids[0]],projection:projection,interpolation:.nearest)).apply(to:&a);try Command.transformLayers(.init(layerIDs:ids,projection:projection,interpolation:.nearest)).apply(to:&b);XCTAssertEqual(a,b)
    source.layers[1].protection = .position;let before=source;for command in [Command.moveLayers(.init(layerIDs:[ids[0]],dx:3,dy:2)),.transform(ids[0],matrix,.nearest),.transformLayers(.init(layerIDs:[ids[0]],projection:projection))]{a=source;XCTAssertThrowsError(try command.apply(to:&a));XCTAssertEqual(a,before)}
  }
  func testCopyMoveAndDuplicationCreateIndependentInternalLinkGroups()throws{
    var source=try fixture();let ids=Array(source.layers.prefix(2).map(\.id));try Command.layerLinks(.link(ids)).apply(to:&source);var d=source;try Command.moveLayers(.init(layerIDs:[ids[0]],dx:4,dy:3,copy:true)).apply(to:&d);let copies=d.layers.filter{!source.layers.map(\.id).contains($0.id)};XCTAssertEqual(copies.count,2);XCTAssertEqual(Set(copies.compactMap(\.linkID)).count,1);XCTAssertNotEqual(copies[0].linkID,source.layers[0].linkID);for original in source.layers{XCTAssertEqual(d.layers.first{$0.id==original.id},original)};for copy in copies{let original=try XCTUnwrap(source.layers.first{copy.name==$0.name+" copy"});XCTAssertEqual(copy.content,original.content);XCTAssertEqual(copy.x,original.x+4);XCTAssertEqual(copy.y,original.y+3)}
    var single=source;try Command.duplicateLayer(ids[0]).apply(to:&single);XCTAssertNil(single.layers.first{!source.layers.map(\.id).contains($0.id)}?.linkID)
  }
  func testDeletionPrunesSingletonAndTransferKeepsOnlyCopiedRelationships()throws{
    var source=try fixture();let ids=Array(source.layers.prefix(2).map(\.id));try Command.layerLinks(.link(ids)).apply(to:&source);var d=source;try Command.deleteLayer(ids[0]).apply(to:&d);XCTAssertNil(d.layers.first{$0.id==ids[1]}?.linkID);let single=try LayerDuplication.newDocument(from:source,selected:[ids[0]],documentName:"One");XCTAssertNil(single.layers[0].linkID);let pair=try LayerDuplication.newDocument(from:source,selected:Set(ids),documentName:"Pair");XCTAssertEqual(pair.layers.count,2);XCTAssertNotNil(pair.layers[0].linkID);XCTAssertEqual(pair.layers[0].linkID,pair.layers[1].linkID);XCTAssertNotEqual(pair.layers[0].linkID,source.layers[0].linkID)
  }
  func testNative84RoundTripLegacyAdmissionAndVersionDowngradeGuard()throws{
    var d=try fixture();let old=d;try Command.layerLinks(.link(Array(d.layers.prefix(2).map(\.id)))).apply(to:&d);try Command.layerLinks(.enabled([d.layers[1].id],false)).apply(to:&d);XCTAssertEqual(d.minimumArchiveVersion,84);let bytes=try NativeArchive.encodeChunked(d);XCTAssertEqual(try NativeArchive.decode(bytes),d);XCTAssertEqual(try NativeArchive.decode(NativeArchive.encodeChunked(old)),old);XCTAssertLessThan(old.minimumArchiveVersion,84)
    var wrong=bytes;wrong.replaceSubrange(8..<12,with:Data([0,0,0,83]));XCTAssertThrowsError(try NativeArchive.decode(wrong))
  }
  func testHistoryPortableActionsNoOpsInvalidAndCancellationPublishAtomically()async throws{
    let source=try fixture();var s=EditorSession(document:source);try s.startActionRecording(name:"Links");let ids=Array(source.layers.prefix(2).map(\.id));try s.execute(.layerLinks(.link(ids)));try s.execute(.moveLayers(.init(layerIDs:[ids[0]],dx:3,dy:2)));let result=s.document;XCTAssertEqual(s.undoStack.count,2);var replay=source;try XCTUnwrap(s.actionRecording?.snapshot).apply(to:&replay);XCTAssertEqual(replay,result);try s.undo();try s.undo();XCTAssertEqual(s.document,source);try s.redo();try s.redo();XCTAssertEqual(s.document,result);let count=s.undoStack.count;try s.execute(.layerLinks(.link(ids)));XCTAssertEqual(s.undoStack.count,count)
    for command in [Command.layerLinks(.link([ids[0]])),.layerLinks(.link([UUID(),ids[0]])),.layerLinks(.link([ids[0],ids[0]])),.moveLayers(.init(layerIDs:[UUID()],dx:1,dy:1)),.moveLayers(.init(layerIDs:[ids[0]],dx:1_000_001,dy:0))]{var d=source;XCTAssertThrowsError(try command.apply(to:&d));XCTAssertEqual(d,source)}
    let task=Task{while !Task.isCancelled{await Task.yield()};var d=source;try Command.moveLayers(.init(layerIDs:ids,dx:3,dy:2,copy:true)).apply(to:&d)};task.cancel();do{try await task.value;XCTFail()}catch{XCTAssertTrue(error is CancellationError)}
  }
  func testSparseMaximumDimensionMoveCopyRetainsOriginalPlaneAndAllSamples()throws{
    var d=try CraftDocument(width:300000,height:300000),pixels=try Surface(width:300000,height:300000);pixels.setPixel(x:65,y:65,.white);let a=Layer(name:"LargeA",content:.raster(pixels)),b=Layer(name:"LargeB",content:.raster(pixels));d.layers=[a,b];d.activeLayerID=b.id;try Command.layerLinks(.link([a.id,b.id])).apply(to:&d);let original=d;try Command.moveLayers(.init(layerIDs:[a.id],dx:32,dy:16,copy:true)).apply(to:&d);XCTAssertEqual(d.layers.count,4);for layer in d.layers{guard case .raster(let p)=layer.content else{return XCTFail()};XCTAssertEqual(p.width,300000);XCTAssertEqual(p.height,300000);XCTAssertEqual(p.pixel(x:65,y:65),.white);XCTAssertLessThan(p.allocatedBytes,2_097_152)};for layer in original.layers{XCTAssertEqual(d.layers.first{$0.id==layer.id},layer)}
  }
}
